const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
// HARDCODED (do NOT read from sov_config — its aiAnswers has stale engines/samples that override the intended run)
const engines=['openai','anthropic'];
const samples=1;
const version=1;
const prompts=await this.helpers.httpRequest({method:'GET',url:SB+'/geo_prompts?select=id,topic,prompt&active=eq.true&order=id',headers:H,json:true});
if(!prompts||!prompts.length)return [];
const d=new Date();const u=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));
const monday=new Date(u.getTime()-(((u.getUTCDay()+6)%7)*86400000));
const week_start=monday.toISOString().slice(0,10);
const out=[];
for(const engine of engines){
  for(let pi=0;pi<prompts.length;pi++){
    for(let si=0;si<samples;si++){
      const p=prompts[pi];
      const prompt=p.prompt;
      let body=null;
      if(engine==='openai')body={model:'gpt-4o-search-preview',max_tokens:700,web_search_options:{},messages:[{role:'user',content:prompt}]};
      else if(engine==='anthropic')body={model:'claude-sonnet-4-5',max_tokens:700,temperature:0.7,tools:[{type:'web_search_20250305',name:'web_search',max_uses:1}],messages:[{role:'user',content:prompt}]};
      else if(engine==='perplexity')body={model:'sonar',temperature:0.7,max_tokens:700,messages:[{role:'user',content:prompt}]};
      out.push({json:{engine,prompt_idx:pi,sample_idx:si,prompt,prompt_id:p.id,topic:p.topic,week_start,prompt_version:version,body}});
    }
  }
}
return out;

const SB='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const KEY='<REDACTED_SUPABASE_JWT>';
const H={apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json'};
const req=async(method,path,body,prefer)=>{const h={...H};if(prefer)h.Prefer=prefer;return this.helpers.httpRequest({method,url:SB+path,headers:h,body,json:true});};
// roster for brand detection (word-boundary match on names + aliases)
const comps=await req('GET','/competitors?select=name,aliases&active=eq.true');
const esc=(s)=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const brandPats=comps.map(c=>{const names=[c.name,...(c.aliases||[])].filter(Boolean);return {brand:c.name,re:new RegExp('\\b('+names.map(esc).join('|')+')\\b','i')};});
// Robust recovery: iterate merged input; map each response item back to its source
// queue item via n8n paired-item chain (survives switch + httpRequest).
const input=$input.all();
const rows=[];
for(let i=0;i<input.length;i++){
  const a=(input[i]&&input[i].json)||{};
  let src=null;
  try{src=$('Build Sample Queue').itemMatching(i).json;}catch(e){src=null;}
  if(!src)continue;
  const engine=src.engine,prompt_id=src.prompt_id,topic=src.topic,week_start=src.week_start;
  let text='';
  if(a.error){text='';}
  else if(a.choices&&a.choices[0]&&a.choices[0].message){text=a.choices[0].message.content||'';}
  else if(Array.isArray(a.content)){text=a.content.filter(c=>c.type==='text').map(c=>c.text).join('\n');}
  if(!text)continue; // skip errored / empty answers
  const matched=[];
  for(const bp of brandPats){const m=text.match(bp.re);if(m)matched.push({company:bp.brand,idx:m.index});}
  matched.sort((x,y)=>x.idx-y.idx);
  const mentions=matched.map((m,r)=>({company:m.company,position:r+1}));
  rows.push({prompt_id,topic,engine,week_start,web_search:true,answer:text.slice(0,6000),mentions});
}
if(!rows.length)return [{json:{written:0,note:'no answered items'}}];
for(let i=0;i<rows.length;i+=50){
  try{await req('POST','/geo_results',rows.slice(i,i+50),'return=minimal');}catch(e){return [{json:{written:i,error:'geo_results write failed: '+String(e.message||e).slice(0,300)}}];}
}
return [{json:{week:rows[0].week_start,written:rows.length,engines:[...new Set(rows.map(r=>r.engine))]}}];
